<template>
  <el-dialog
    title="修改个人信息"
    :visible.sync="dialogFormVisible"
    :destroy-on-close="true"
    width="30%"
    center
  >
    <el-form :model="form" :rules="rules" ref="infoForm">
      <el-form-item v-if="scene === 'nickname'" prop="nickname">
        <el-input
          v-model="form.nickname"
          autocomplete="off"
          maxlength="32"
          show-word-limit
        ></el-input>
      </el-form-item>
      <el-form-item label="" v-if="scene === 'avatar'">
        <vr-upload
          uploadClass="avatar-container"
          tip="建议尺寸：150 X 150"
          listType
          :cropImg="true"
          :autoUpload="false"
          :autoCropWidth="150"
          :autoCropHeight="150"
          :cropDialogModalAppendToBody="false"
          :cropDialogAppendToBody="true"
          :cropDialogDestroyOnClose="true"
          cropDialogWidth="800px"
          cropDialogTop="8vh"
          :fileList="[
            {
              name: form.nickname,
              url: form.avatar_full,
              path: form.avatar,
            },
          ]"
          @onSuccess="onAvatarUploadSuccess"
        />
      </el-form-item>
      <el-form-item v-if="scene === 'intro'" prop="intro">
        <el-input
          v-model="form.intro"
          autocomplete="off"
          type="textarea"
          placeholder="请输入简介"
          maxlength="1000"
          rows="10"
          show-word-limit
        ></el-input>
      </el-form-item>
      <el-form-item label="" v-if="scene === 'phone'" prop="phone">
        <el-input
          v-model="form.phone"
          autocomplete="off"
          placeholder="手机号"
        ></el-input>
      </el-form-item>
      <el-form-item label="" v-if="scene === 'email'" prop="email">
        <el-input
          v-model="form.email"
          autocomplete="off"
          placeholder="邮箱"
        ></el-input>
      </el-form-item>
      <el-form-item label="" v-if="scene === 'password'" prop="password">
        <el-input
          type="password"
          v-model="form.password"
          autocomplete="off"
          placeholder="密码"
        ></el-input>
      </el-form-item>
      <el-form-item label="" v-if="scene === 'password'" prop="password2">
        <el-input
          type="password"
          v-model="form.password2"
          placeholder="确认密码"
          autocomplete="off"
        ></el-input>
      </el-form-item>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="cancel">取 消</el-button>
      <el-button type="primary" @click="submit">确 定</el-button>
    </div>
  </el-dialog>
</template>
<script>
import { editInfo } from '@/api/user'
const defaultForm = {
  nickname: '',
  avatar: '',
  intro: '',
  phone: '',
  email: '',
  password: '',
  password2: '',
}
export default {
  name: 'VIPEdit',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  props: {},
  data() {
    return {
      vipInfo: null,
      dialogFormVisible: false,
      formLabelWidth: '140px',
      scene: 'nickname',
      submitLoading: false,
      form: Object.assign({}, defaultForm),
    }
  },
  computed: {
    rules() {
      switch (this.scene) {
        case 'nickname':
          return {
            nickname: [
              { required: true, message: '请输入用户名', trigger: 'blur' },
              {
                min: 1,
                max: 32,
                message: '长度在 1 到 32 个字符',
                trigger: 'blur',
              },
            ],
          }
        case 'intro':
          return {
            intro: [{ max: 1000, message: '最多1000个字符', trigger: 'blur' }],
          }
        case 'phone':
          return {
            phone: [
              {
                validator: (rule, value, callback) => {
                  const phoneRegex = /^1[3-9]\d{9}$/
                  if (!value) {
                    callback(new Error('请输入手机号'))
                  } else if (!phoneRegex.test(value)) {
                    callback(new Error('请输入有效的手机号'))
                  } else {
                    callback()
                  }
                },
                trigger: 'blur',
              },
            ],
          }
        case 'email':
          return {
            email: [
              {
                type: 'email',
                required: true,
                message: '请输入正确的邮箱号',
                trigger: 'blur',
              },
            ],
          }
        case 'password':
        default:
          return {
            password: [
              {
                validator: (rule, value, callback) => {
                  if (value === '') {
                    callback(new Error('请输入密码'))
                  } else {
                    if (this.form.password2) {
                      this.$refs.infoForm.validateField('password2')
                    }
                    callback()
                  }
                },
                trigger: 'blur',
              },
            ],
            password2: [
              {
                validator: (rule, value, callback) => {
                  if (value === '') {
                    callback(new Error('请再次输入密码'))
                  } else if (value !== this.form.password) {
                    callback(new Error('两次输入密码不一致!'))
                  } else {
                    callback()
                  }
                },
                trigger: 'blur',
              },
            ],
          }
      }
    },
    model() {
      if ('nickname' === this.scene) {
        return {
          nickname: this.form.nickname,
        }
      }

      if ('avatar' === this.scene) {
        return {
          avatar: this.form.avatar,
        }
      }

      if ('phone' === this.scene) {
        return {
          phone: this.form.phone,
        }
      }

      if ('email' === this.scene) {
        return {
          email: this.form.email,
        }
      }

      if ('intro' === this.scene) {
        return {
          intro: this.form.intro,
        }
      }

      return {
        password: this.form.password,
        password2: this.form.password2,
      }
    },
  },
  methods: {
    open(scene = 'nickname', vipInfo) {
      this.dialogFormVisible = true
      this.vipInfo = vipInfo
      this.scene = scene
      this.$nextTick(() => {
        this.$refs.infoForm.clearValidate()
        this.form = Object.assign(defaultForm, {
          nickname: this.vipInfo.nickname,
          avatar: this.vipInfo.avatar,
          avatar_full: this.vipInfo.avatar_full,
          intro: this.vipInfo.intro,
          phone: this.vipInfo.phone,
          email: this.vipInfo.email,
        })
      })
    },
    // 上传成功
    onAvatarUploadSuccess(data) {
      this.form.avatar = data.path
    },
    cancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.infoForm.resetFields()
      this.$refs.infoForm.clearValidate()
      this.dialogFormVisible = false
    },
    submit() {
      this.submitLoading = true
      this.$refs.infoForm.validate((valid, errs) => {
        if (valid) {
          editInfo(this.vipInfo.uuid, this.model)
            .then(async () => {
              this.cancel()
              this.$emit('changed', this.scene, this.form.password)
            })
            // eslint-disable-next-line no-unused-vars
            .catch((_err) => {
              setTimeout(() => {
                this.submitLoading = false
              }, 1000)
              // this.$message.error(_err.message)
            })
        } else {
          setTimeout(() => {
            this.submitLoading = false
          }, 1500)
          for (const key in errs) {
            this.$message.error(errs[key][0].message)
            return false
          }
        }
      })
    },
  },
}
</script>
